begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select plan(15);
create temp table projection_input(data jsonb);
insert into projection_input values('{"today":"2026-10-12","fallbackCycleDay":5,"cashBalanceCents":300000,"safetyReserveCents":0,"essentialNeedCents":0,"commitments":[],"statements":[],"people":[],"reserves":[],"scheduled":[]}');
select is(private.calculate_free_to_spend((select data from projection_input))->>'horizonEnd','2026-11-05','Fallback horizon is exclusive next cycle');
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{conservative,valueCents}')::bigint,300000::bigint,'Empty scenario preserves cash');
update projection_input set data=data||'{"reserves":[{"id":"ipva","holdingMode":"virtual","active":true,"balanceCents":180000}],"commitments":[{"id":"ipva-bill","direction":"outflow","certainty":"confirmed","effectiveDueOn":"2026-10-20","dueCents":240000,"paidCents":0,"paymentLiquidity":"cash","reserveId":"ipva"}]}';
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{conservative,valueCents}')::bigint,60000::bigint,'CT-GOAL-002 obligation and virtual reserve counted once');
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{conservative,uncoveredReserveCents}')::bigint,60000::bigint,'Uncovered reserve difference is explicit');
select is((select (item->>'coveredCents')::bigint from jsonb_array_elements(private.calculate_free_to_spend((select data from projection_input))#>'{conservative,items}') item where item->>'id'='ipva-bill'),180000::bigint,'Details agree with reserve coverage');
update projection_input set data=data||'{"cashBalanceCents":200000,"reserves":[{"id":"travel","holdingMode":"virtual","active":true,"balanceCents":80000}],"commitments":[{"id":"latest","direction":"outflow","certainty":"confirmed","effectiveDueOn":"2026-11-01","dueCents":50000,"paidCents":0,"paymentLiquidity":"cash","reserveId":"travel"}],"statements":[{"id":"future","status":"future","effectiveDueOn":"2026-10-30","remainingIncludingScheduledCents":50000,"reservedUnconsumed":[{"reserveId":"travel","amountCents":50000,"occurredOn":"2026-10-25"}]}],"scheduled":[{"id":"early","occurredOn":"2026-10-20","netCashCents":-50000,"reservedOutflows":[{"reserveId":"travel","amountCents":50000}]}]}';
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{conservative,valueCents}')::bigint,50000::bigint,'One reserve shared chronologically across all sources');
select is((select (item->>'coveredCents')::bigint from jsonb_array_elements(private.calculate_free_to_spend((select data from projection_input))#>'{conservative,items}') item where item->>'id'='early:travel'),50000::bigint,'Earliest scheduled payment receives coverage first');
select is((select (item->>'coveredCents')::bigint from jsonb_array_elements(private.calculate_free_to_spend((select data from projection_input))#>'{conservative,items}') item where item->>'id'='future:travel'),30000::bigint,'Future card receives remaining reserve coverage');
update projection_input set data=data||'{"cashBalanceCents":400000,"reserves":[],"statements":[],"scheduled":[],"people":[{"id":"joao","balanceCents":40000,"openReminderDates":["2026-10-15"]}],"commitments":[{"id":"rent","direction":"outflow","certainty":"confirmed","effectiveDueOn":"2026-10-13","dueCents":150000,"paidCents":0,"paymentLiquidity":"cash"},{"id":"energy","direction":"outflow","certainty":"estimated","effectiveDueOn":"2026-10-20","dueCents":20000,"paidCents":0,"paymentLiquidity":"cash","actualHistoryCents":[33000,36000,39000]},{"id":"commission","direction":"inflow","certainty":"estimated","effectiveDueOn":"2026-10-20","dueCents":120000,"paidCents":0,"paymentLiquidity":"cash","actualHistoryCents":[90000,100000,140000]},{"id":"freelance","direction":"inflow","certainty":"conditional","effectiveDueOn":"2026-10-26","dueCents":80000,"paidCents":0,"paymentLiquidity":"cash"}]}';
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{conservative,valueCents}')::bigint,304000::bigint,'CT-LFG-010 conservative official result');
select is((private.calculate_free_to_spend((select data from projection_input))#>>'{expected,valueCents}')::bigint,470000::bigint,'CT-LFG-010 expected official result');
select is(private.free_considered('{"direction":"inflow","certainty":"estimated","dueCents":120000,"paidCents":70000,"actualHistoryCents":[150000,160000,170000]}'::jsonb,false),50000::bigint,'Contradictory history is capped by forecast minus paid');
select is(private.free_considered('{"direction":"outflow","certainty":"estimated","dueCents":10,"paidCents":0,"actualHistoryCents":[10,11]}'::jsonb,false),11::bigint,'Estimated expense history rounds half up');
select throws_ok($$select private.calculate_free_to_spend('{"today":"2026-10-12","fallbackCycleDay":5,"cashBalanceCents":0,"safetyReserveCents":-1,"essentialNeedCents":0,"commitments":[],"statements":[],"people":[],"reserves":[],"scheduled":[]}'::jsonb)$$,'23514',null,'Negative safety reserve rejected');
select ok(not has_function_privilege('authenticated','private.calculate_free_to_spend(jsonb)','EXECUTE'),'Client cannot supply arbitrary projection totals');
select ok(has_function_privilege('authenticated','api.free_to_spend_summary(uuid,date)','EXECUTE'),'Canonical member read endpoint is available');
select * from finish();
rollback;
